result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/gitmini/gitmini.py", "content": "#!/usr/bin/env python3
"""gitmini — a working subset of git's object model in pure Python.

Implements the content-addressed plumbing (blob / tree / commit objects,
zlib-compressed under .gitmini/objects/aa/bbbb...), a JSON staging index,
and the porcelain commands init/add/commit/log/checkout-file.

Object framing and hashing are byte-for-byte git-compatible:
    sha1("<type> <byte-length>\\0" + <payload>)
so e.g. `git hash-object` agrees with gitmini on any blob, and tree ids
match what `git write-tree` produces for identical content.

No use of the git binary anywhere in this file.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import stat
import sys
import time
import zlib
from datetime import datetime

GITMINI_DIR = ".gitmini"
HEX = set("0123456789abcdef")


class GitMiniError(Exception):
    """User-facing error (unknown object, not a repo, missing path, ...)."""


# ---------------------------------------------------------------------------
# Repository discovery / layout
# ---------------------------------------------------------------------------

def repo_root(start: str = ".") -> str:
    """Walk up from *start* until a directory containing .gitmini is found."""
    d = os.path.abspath(start)
    while True:
        if os.path.isdir(os.path.join(d, GITMINI_DIR)):
            return d
        parent = os.path.dirname(d)
        if parent == d:
            raise GitMiniError(
                f"fatal: not a gitmini repository (no {GITMINI_DIR} found)"
            )
        d = parent


def obj_path(root: str, sha: str) -> str:
    return os.path.join(root, GITMINI_DIR, "objects", sha[:2], sha[2:])


def head_path(root: str) -> str:
    return os.path.join(root, GITMINI_DIR, "HEAD")


def index_path(root: str) -> str:
    return os.path.join(root, GITMINI_DIR, "index.json")


def cmd_init(dirpath: str = ".") -> str:
    root = os.path.abspath(dirpath)
    gm = os.path.join(root, GITMINI_DIR)
    os.makedirs(os.path.join(gm, "objects"), exist_ok=True)
    hp = head_path(root)
    if not os.path.exists(hp):
        with open(hp, "w") as f:  # empty HEAD == unborn branch
            f.write("")
    ip = index_path(root)
    if not os.path.exists(ip):
        with open(ip, "w") as f:
            json.dump({}, f)
    print(f"Initialized empty gitmini repository in {gm}")
    return root


# ---------------------------------------------------------------------------
# Object store: hash / write / read  (git-compatible framing)
# ---------------------------------------------------------------------------

def hash_object(data: bytes, obj_type: str = "blob", root: str | None = None,
                write: bool = True) -> str:
    """Content-address *data* exactly like git does and optionally store it.

    Returns the real sha1 of '<type> <len>\\0<data>' — identical to what
    `git hash-object` computes.
    """
    full = obj_type.encode() + b" " + str(len(data)).encode() + b"\0" + data
    sha = hashlib.sha1(full).hexdigest()
    if write:
        p = obj_path(repo_root(root) if root else os.getcwd(), sha)
        if not os.path.exists(p):
            os.makedirs(os.path.dirname(p), exist_ok=True)
            tmp = p + ".tmp%d" % os.getpid()
            with open(tmp, "wb") as f:
                f.write(zlib.compress(full))
            os.replace(tmp, p)
    return sha


def read_object(root: str, sha: str) -> tuple[str, bytes]:
    """Return (type, payload) for an existing object id.

    Raises GitMiniError for malformed or absent ids (the 'unknown object'
    error path).
    """
    sha = sha.lower()
    if len(sha) != 40 or not set(sha) <= HEX:
        raise GitMiniError(f"error: unknown object id: {sha}")
    p = obj_path(root, sha)
    if not os.path.isfile(p):
        raise GitMiniError(f"error: unknown object id: {sha}")
    with open(p, "rb") as f:
        full = zlib.decompress(f.read())
    header, _, payload = full.partition(b"\0")
    obj_type, size_s = header.decode("ascii").split(" ", 1)
    size = int(size_s)
    if len(payload) != size:
        raise GitMiniError(f"error: corrupted object {sha}: size mismatch")
    return obj_type, payload


def resolve(root: str, ref: str) -> str:
    """Resolve 'HEAD' or a full/prefix commit id to a full 40-hex id."""
    ref = ref.strip()
    if ref == "HEAD":
        with open(head_path(root)) as f:
            sha = f.read().strip()
        if not sha:
            raise GitMiniError("fatal: HEAD does not point to any commit yet")
        read_object(root, sha)  # existence check
        return sha
    r = ref.lower()
    if len(r) == 40 and set(r) <= HEX:
        read_object(root, r)  # raises on unknown id
        return r
    if 4 <= len(r) < 40 and set(r) <= HEX:
        matches = []
        fan = os.path.join(root, GITMINI_DIR, "objects", r[:2])
        if os.path.isdir(fan):
            for rest in sorted(os.listdir(fan)):
                if (r[:2] + rest).startswith(r):
                    matches.append(r[:2] + rest)
        if len(matches) == 1:
            return matches[0]
        if len(matches) > 1:
            raise GitMiniError(f"error: ambiguous object id prefix: {ref}")
    raise GitMiniError(f"error: unknown object id: {ref}")


# ---------------------------------------------------------------------------
# Trees
# ---------------------------------------------------------------------------

def _tree_object(root: str, entries: list[tuple[bytes, str, str]]) -> str:
    """Serialize entries [(name, mode, sha)] git-style; returns tree sha."""
    # git sorts by raw name bytes, with trees compared as name + '/'
    entries.sort(key=lambda e: e[0] + (b"/" if e[1] == "40000" else b""))
    buf = b"".join(
        mode.encode() + b" " + name + b"\0" + bytes.fromhex(sha)
        for name, mode, sha in entries
    )
    return hash_object(buf, "tree", root)


def _insert(index_tree: dict, parts: list[str], info: dict) -> None:
    cur = index_tree
    for part in parts[:-1]:
        nxt = cur.setdefault(part, {})
        if "_sha" in nxt:  # file/dir conflict — file wins, like a flat stage
            return
        cur = nxt
    leaf = cur.get(parts[-1])
    if isinstance(leaf, dict) and "_sha" not in leaf:
        return  # a directory already occupies this name
    cur[parts[-1]] = {"_sha": info["sha"], "_mode": info["mode"]}


def tree_from_index(root: str, index: dict[str, dict]) -> str:
    """Build nested tree objects from {relpath: {'sha','mode'}} (the stage)."""
    top: dict = {}
    for relpath in sorted(index):
        _insert(top, relpath.split("/"), index[relpath])

    def ser(node: dict) -> str | None:
        entries = []
        for name, val in node.items():
            nb = name.encode()
            if "_sha" in val:
                entries.append((nb, val["_mode"], val["_sha"]))
            else:
                sub = ser(val)
                if sub is not None:  # empty dirs are omitted, like git
                    entries.append((nb, "40000", sub))
        if not entries:
            return None
        return _tree_object(root, entries)

    return ser(top) or _tree_object(root, [])


def worktree_index(root: str, subdir: str | None = None) -> dict[str, dict]:
    """Stage an entire worktree (like `git add -A`) into an index dict."""
    base = subdir or root
    index: dict[str, dict] = {}
    for dirpath, dirnames, filenames in os.walk(base):
        dirnames[:] = [d for d in dirnames if d != GITMINI_DIR]
        for fn in filenames:
            fp = os.path.join(dirpath, fn)
            rel = os.path.relpath(fp, root).replace(os.sep, "/")
            with open(fp, "rb") as f:
                data = f.read()
            exec_bit = bool(os.stat(fp).st_mode & stat.S_IXUSR)
            index[rel] = {
                "sha": hash_object(data, "blob", root),
                "mode": "100755" if exec_bit else "100644",
            }
    return index


def lookup_in_tree(root: str, tree_sha: str, parts: list[str]) -> str:
    """Descend a tree along *parts*; return the blob sha at the leaf."""
    obj_type, data = read_object(root, tree_sha)
    if obj_type != "tree":
        raise GitMiniError(f"error: not a tree object: {tree_sha}")
    want = parts[0]
    i = 0
    while i < len(data):
        sp = data.index(b" ", i)
        nul = data.index(b"\0", sp)
        mode = data[i:sp].decode()
        name = data[sp + 1:nul].decode()
        sha = data[nul + 1:nul + 21].hex()
        i = nul + 21
        if name == want:
            if len(parts) == 1:
                if mode == "40000":
                    raise GitMiniError(f"error: '{'/'.join(parts)}' is a directory")
                return sha
            return lookup_in_tree(root, sha, parts[1:])
    raise GitMiniError(
        f"error: path '{'/'.join(parts)}' does not exist in this commit"
    )


# ---------------------------------------------------------------------------
# Commits
# ---------------------------------------------------------------------------

def _local_tz() -> str:
    off = -(time.altzone if (time.daylight and time.localtime().tm_isdst)
            else time.timezone)
    sign = "+" if off >= 0 else "-"
    off = abs(off)
    return "%s%02d%02d" % (sign, off // 3600, (off % 3600) // 60)


def parse_commit(payload: bytes) -> dict:
    header, _, message = payload.partition(b"\n\n")
    info: dict = {"parents": [], "message": message.decode(errors="replace")}
    ident = {}
    for line in header.decode(errors="replace").splitlines():
        key, _, val = line.partition(" ")
        if key == "parent":
            info["parents"].append(val)
        elif key in ("tree", "author", "committer"):
            info[key] = val
        elif key in ("author", "committer"):
            pass
        if key in ("author", "committer"):
            ident[key] = val
    info["author_ident"] = ident.get("author", "")
    return info


def load_commit(root: str, sha: str) -> dict:
    obj_type, payload = read_object(root, sha)
    if obj_type != "commit":
        raise GitMiniError(f"error: not a commit object: {sha}")
    info = parse_commit(payload)
    info["sha"] = sha
    return info


def read_head(root: str) -> str:
    with open(head_path(root)) as f:
        return f.read().strip()


def get_index(root: str) -> dict:
    try:
        with open(index_path(root)) as f:
            return json.load(f)
    except FileNotFoundError:
        return {}


def save_index(root: str, index: dict) -> None:
    with open(index_path(root), "w") as f:
        json.dump(index, f, indent=1, sort_keys=True)


# ---------------------------------------------------------------------------
# Porcelain commands
# ---------------------------------------------------------------------------

def cmd_add(root: str, paths: list[str]) -> None:
    index = get_index(root)
    added = 0
    for p in paths:
        ap = os.path.abspath(p)
        if os.path.isdir(ap):
            sub = worktree_index(root, ap)
            index.update(sub)
            added += len(sub)
        elif os.path.isfile(ap):
            rel = os.path.relpath(ap, root).replace(os.sep, "/")
            with open(ap, "rb") as f:
                data = f.read()
            exec_bit = bool(os.stat(ap).st_mode & stat.S_IXUSR)
            index[rel] = {
                "sha": hash_object(data, "blob", root),
                "mode": "100755" if exec_bit else "100644",
            }
            added += 1
        else:
            raise GitMiniError(f"fatal: pathspec '{p}' did not match any files")
    save_index(root, index)
    for rel in sorted(index):
        print(f"staged: {rel} -> {index[rel]['sha'][:12]}")
    print(f"{added} path(s) staged.")


def cmd_commit(root: str, message: str) -> str:
    index = get_index(root)
    if not index:
        raise GitMiniError("nothing to commit (stage files with `gitmini add`)")
    tree_sha = tree_from_index(root, index)
    parent = read_head(root) or None
    ts = int(time.time())
    tz = _local_tz()
    who = "{0} <{1}>".format(
        os.environ.get("GITMINI_AUTHOR_NAME", "gitmini"),
        os.environ.get("GITMINI_AUTHOR_EMAIL", "gitmini@example.com"),
    )
    lines = [f"tree {tree_sha}"]
    if parent:
        lines.append(f"parent {parent}")
    lines += [
        f"author {who} {ts} {tz}",
        f"committer {who} {ts} {tz}",
    ]
    payload = ("\n".join(lines)).encode() + b"\n\n" + message.encode() + b"\n"
    sha = hash_object(payload, "commit", root)
    with open(head_path(root), "w") as f:
        f.write(sha + "\n")
    kind = "root" if not parent else "child"
    print(f"[{kind} commit {sha[:12]}] {message.splitlines()[0]}")
    print(f" tree: {tree_sha[:12]}  parent: {(parent or '-')[:12]}")
    return sha


def log_commits(root: str) -> list[dict]:
    """Traverse the parent chain from HEAD, newest first."""
    commits = []
    sha = read_head(root)
    seen = set()
    while sha:
        if sha in seen:
            raise GitMiniError(f"error: commit cycle detected at {sha}")
        seen.add(sha)
        info = load_commit(root, sha)
        commits.append(info)
        parents = info["parents"]
        if len(parents) > 1:
            raise GitMiniError("error: merge commits are outside gitmini's scope")
        sha = parents[0] if parents else ""
    return commits


def cmd_log(root: str) -> None:
    commits = log_commits(root)
    if not commits:
        print("No commits yet.")
        return
    for i, c in enumerate(commits):
        if i:
            print()
        print(f"commit {c['sha']}")
        for p in c["parents"]:
            print(f"parent {p}")
        print(f"Author: {c['author_ident']}")
        ts = int(c["author_ident"].rsplit(" ", 2)[-2])
        print(f"Date:   {datetime.fromtimestamp(ts):%Y-%m-%d %H:%M:%S %z}")
        print()
        for line in c["message"].rstrip("\n").splitlines():
            print(f"    {line}")


def cmd_checkout_file(root: str, ref: str, path: str) -> bytes:
    """Restore *path* as it existed in commit *ref*, byte-exactly."""
    commit_sha = resolve(root, ref)
    info = load_commit(root, commit_sha)
    parts = [p for p in path.replace(os.sep, "/").split("/") if p]
    blob_sha = lookup_in_tree(root, info["tree"], parts)
    obj_type, data = read_object(root, blob_sha)
    if obj_type != "blob":
        raise GitMiniError(f"error: not a blob: {blob_sha}")
    parent_dir = os.path.dirname(path)
    if parent_dir:
        os.makedirs(parent_dir, exist_ok=True)
    with open(path, "wb") as f:
        f.write(data)
    print(f"restored '{path}' from {commit_sha[:12]} (blob {blob_sha[:12]}, "
          f"{len(data)} bytes)")
    return data


# ---------------------------------------------------------------------------
# CLI entry point
# ---------------------------------------------------------------------------

def run(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(prog="gitmini",
                                     description="a tiny pure-Python git subset")
    sub = parser.add_subparsers(dest="cmd", required=True)

    p = sub.add_parser("init", help="create an empty gitmini repository")
    p.add_argument("directory", nargs="?", default=".")

    p = sub.add_parser("add", help="stage files/directories into the index")
    p.add_argument("paths", nargs="+")

    p = sub.add_parser("commit", help="record the staged index as a commit")
    p.add_argument("-m", "--message", required=True)

    sub.add_parser("log", help="walk the commit chain from HEAD")

    p = sub.add_parser("checkout-file",
                       help="restore a file from a commit (ref may be HEAD or a sha/prefix)")
    p.add_argument("ref")
    p.add_argument("path")

    args = parser.parse_args(argv)
    try:
        if args.cmd == "init":
            cmd_init(args.directory)
        elif args.cmd == "add":
            cmd_add(repo_root(), args.paths)
        elif args.cmd == "commit":
            cmd_commit(repo_root(), args.message)
        elif args.cmd == "log":
            cmd_log(repo_root())
        elif args.cmd == "checkout-file":
            cmd_checkout_file(repo_root(), args.ref, args.path)
    except GitMiniError as exc:
        print(str(exc), file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(run(sys.argv[1:]))
